import axios from 'axios'

const regex = /ws=(.*)\/.*/g
const matches = regex.exec(parent.location.search)
if (matches) {
  const url = matches[1]
  axios.defaults.baseURL = `http://${url}`
}

if (process.env.NODE_ENV === 'development') {
  // 开发时添加 mock 数据
  const mockHttp = require('./mock').default
  mockHttp(axios)
}

export default axios
